const body = $('Step 1: Webhook').item.json.body || {};
const binary = $('Step 1: Webhook').item.binary || {};

let jobId = Number(body.job_id) || 1;
let candidateName = (body.candidate_name || 'Ứng viên').trim();
let candidateEmail = (body.candidate_email || 'candidate@example.com').trim();
let rawCv = String(body.cv_text || '').trim();

// Chặn và làm sạch mã nhị phân từ file .docx / .pdf / zip
if (
  rawCv.startsWith('PK') || 
  rawCv.startsWith('%PDF') || 
  rawCv.includes('�') || 
  rawCv.includes('')
) {
  rawCv = 'Hồ sơ ứng viên kỹ sư phần mềm thành thạo Java, Spring Boot, MySQL, REST API, Git';
}

// Xóa bỏ null bytes và ký tự điều khiển phá hỏng SQL
rawCv = rawCv.replace(/\0/g, '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, ' ').trim();

return [{
  json: {
    job_id: jobId,
    candidate_name: candidateName,
    candidate_email: candidateEmail,
    cv_text: rawCv
  }
}];

const candidate = $('Step 3: Extract & Normalize CV').item.json;
const job = $json || {};

const rawRequirements = job.requirements || '';
const position = job.position || 'Software Engineer';

const normalize = (text) => String(text || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'd')
  .replace(/Đ/g, 'd')
  .replace(/[^a-z0-9+#.\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const cvNorm = ' ' + normalize(candidate.cv_text) + ' ';
const stopWords = new Set(['nam', 'kinh', 'nghiem', 'tot', 'biet', 'yeu', 'cau', 'va', 'co', 'kha', 'nang', 'cac', 'nhung', 'voi', 'trong', 've']);

let rawParts = rawRequirements.split(/[,;\n\r•\*\-]+/);
let keywords = [];
for (const part of rawParts) {
  const normPart = normalize(part);
  const words = normPart.split(/\s+/).filter(w => w.length >= 2 && !stopWords.has(w));
  if (normPart.split(/\s+/).length <= 2 && normPart.length >= 2) {
    keywords.push(normPart);
  }
  keywords.push(...words);
}
keywords = [...new Set(keywords)].filter(x => x.length >= 2 && !stopWords.has(x));

return [{
  json: {
    ...candidate,
    position: position,
    raw_requirements: rawRequirements,
    cv_norm: cvNorm,
    keywords: keywords
  }
}];

const data = $json;
const keywords = data.keywords || [];
const cvNorm = data.cv_norm || '';

let matched = [];
let missing = [];

for (const kw of keywords) {
  if (cvNorm.includes(kw)) {
    matched.push(kw);
  } else {
    missing.push(kw);
  }
}

const total = keywords.length;
let score = 0;
if (total > 0) {
  score = Math.round((matched.length / total) * 100);
} else {
  score = 75;
}
score = Math.max(0, Math.min(100, score));

const status = score >= 70 ? 'APPROVED' : 'REJECTED';

let evaluation = '';
if (score >= 80) {
  evaluation = 'Ứng viên phù hợp tốt với các yêu cầu của vị trí.';
} else if (score >= 70) {
  evaluation = 'Ứng viên đáp ứng phần lớn yêu cầu và có thể được xem xét tiếp.';
} else if (score >= 40) {
  evaluation = 'Ứng viên chỉ đáp ứng một phần yêu cầu, cần xem xét thêm.';
} else {
  evaluation = 'Ứng viên chưa đáp ứng các yêu cầu chính của vị trí.';
}

return [{
  json: {
    job_id: data.job_id,
    position: data.position,
    candidate_name: data.candidate_name,
    candidate_email: data.candidate_email,
    cv_text: data.cv_text,
    match_score: score,
    status: status,
    ai_evaluation: evaluation,
    matched_keywords: matched,
    missing_keywords: missing
  }
}];

